    puntuacionesTitulo: "Scores for a specific session",
    puntuacionesDesc: (sesionesPuntuacion, numComponentes) => `Audit tool: pick a session number within the downloaded window and check the score (sum of the changes of that session and the ${sesionesPuntuacion - 1} previous ones) of the ${numComponentes} components on that exact date, without applying any portfolio or rebalancing rule.`,
    puntuacionesEtiquetaSesion: (min, max, sesionesPuntuacion) => `Session number within the window (between ${min} and ${max} — at least ${sesionesPuntuacion} previous changes are needed):`,
    puntuacionesAplicabilidad: "Only audits selection by price, by volume and by money flow (and their 'low price/volume/flow' antitheses: they're the same scores, just read from the bottom of the table instead of the top). Doesn't apply to random selection (there's no real score to audit), nor to 'Best fundamental selection' or 'Analyst selection' (they have no per-session score: they're a snapshot of today's data, with no daily history available that way — for those two, use 'Fundamental data' and 'Analyst recommendations' further below).",
    puntuacionesEtiquetaCriterio: "Criterion:",
    puntuacionesBotonCargando: "Fetching...",
    puntuacionesBoton: "Check scores",
    puntuacionesResultadoTitulo: (fecha, sesion) => `Scores for ${fecha} (session #${sesion})`,

    variacionIndicesTitulo: "Index changes",
    variacionIndicesDesc: "Downloads the historical closes of the indices themselves (not their components) and shows each index's most recent sessions, with their date, closing value and daily percentage change, so you can check by hand that the data matches what the rest of the app uses. Each index shows its own dates, not a date shared by all: with markets all over the world, requiring the exact same closing day across all of them would be too fragile (one holiday in a single market is enough to break it).",
    descargarPdfBoton: "Download PDF",
    compartirPdfBoton: "Share PDF",
    compartirPdfBotonCargando: "Preparing...",
    compartirPdfNoDisponible: "Couldn't share on this device.",
    variacionIndicesBotonCargando: "Checking...",
    variacionIndicesBoton: "Check index changes",

    componentesEtfTitulo: "Component check via ETF",
    componentesEtfDesc: (etf, nombreIndice) => `Looks up the top 10 holdings on Yahoo Finance of ${etf}, the ETF that tracks the ${nombreIndice}, and compares it with the component list the app uses. Yahoo only exposes an ETF's top 10, never the full list: this is meant to spot at a glance whether a heavily-weighted stock is out of date, not to audit the whole index.`,
    componentesEtfBotonCargando: "Checking...",
    componentesEtfBoton: "Check components via ETF",
    sinEtfsDisponibles: "No UCITS distributing ETFs found meeting the requirements",

    fundamentalesTitulo: "Fundamental data",
    fundamentalesDesc: "Looks up fundamental data on Yahoo Finance for every component of the index, in a single call. Revenue, sales and operating cash flow aren't available here, since they can only be queried one stock at a time, which would mean many requests in a row for large indices.",
    fundamentalesBotonCargando: "Checking...",
    fundamentalesBoton: "Check fundamental data",

    recomendacionesAnalistasTitulo: "Analyst recommendations",
    recomendacionesAnalistasDesc: "Looks up Yahoo Finance's analyst consensus (from strong buy to strong sell) and the number of analysts covering each component of the index, ranked from best to worst consensus, so you can manually audit the ranking used by \"Analyst selection\". Unlike that tool, every component is listed here, including the ones with no valid data (\"N/A\"). Analyst consensus can only be checked one stock at a time, there's no fast whole-index query.",
    recomendacionesAnalistasAvisoIndiceGrande: (n) => `This index has ${n} components: since it's checked one stock at a time, this check can take noticeably longer than for small indices, and there's a somewhat higher chance a particular stock fails to look up (it would show as "N/A", without interrupting the rest).`,
    recomendacionesAnalistasBotonCargando: "Checking analysts...",
    recomendacionesAnalistasBoton: "Check analyst recommendations",
